9	/// Доля съедания стены к касанию, %: `100 × (1 − size_at_touch /
10	/// size_max_before)`; стена без истории размера (`size_max_before ≤ 0`) —
11	/// ноль, чтобы ключ `eaten=` её не выбивал (нечего было съесть).
12	#[allow(clippy::cast_precision_loss)]
13	pub(super) fn eaten_pct(t: &TouchRecord) -> f64 {
14	    if t.size_max_before <= 0 {
15	        return 0.0;
16	    }
17	    100.0 * (1.0 - t.size_at_touch as f64 / t.size_max_before as f64)
18	}
