26	    /// `backtest::touch_view_of_approach`); `None` — сигнал по касаниям.
27	    pub(crate) approaches: Option<Vec<crate::lob::levels::ApproachRecord>>,
28	    /// Ход до касания за `PRE_TOUCH_MS` на каждое касание (S2), для контекста наборов.
29	    pub(crate) rets: Vec<[Option<f64>; 3]>,
30	}
