34	/// `<dir>/touches-<SYMBOL>.csv`, из которого берутся строки этих суток.
35	/// Нет файла на какие-то сутки или в суточном файле чужие сутки — `Err`
36	/// (вызывающий идёт реплеем и пишет причину). Порядок строк — порядок файла,
37	/// он же порядок выдачи трекера.
38	pub(crate) fn cached_touches<'a>(
39	    dir: &Path,
40	    symbol: &str,
41	    days: impl Iterator<Item = &'a String>,
42	    need_ret: bool,
43	) -> anyhow::Result<Vec<DayTouches>> {
44	    let flat = dir.join(format!("touches-{symbol}.csv"));
45	    let mut flat_rows: Option<Vec<crate::commands::lob::touches::TouchRow>> = None;
46	    let mut out = Vec::new();
47	    for day in days {
48	        let per_day = dir.join(day).join(format!("touches-{symbol}.csv"));
49	        let rows: Vec<crate::commands::lob::touches::TouchRow> = if per_day.is_file() {
50	            let rows = crate::commands::lob::touches::read_touches_csv(&per_day)?;
51	            if let Some(bad) = rows.iter().find(|r| r.day != *day) {
52	                anyhow::bail!(
53	                    "{}: строка суток {} в файле суток {day}",
54	                    per_day.display(),
55	                    bad.day
56	                );
57	            }
58	            rows
59	        } else if flat.is_file() {
60	            if flat_rows.is_none() {
61	                flat_rows = Some(crate::commands::lob::touches::read_touches_csv(&flat)?);
62	            }
63	            flat_rows
64	                .as_ref()
65	                .expect("только что прочитан")
66	                .iter()
67	                .filter(|r| r.day == *day)
68	                .cloned()
69	                .collect()
70	        } else {
