) -> anyhow::Result<(Writer<FrameSink>, u32)> {
    claim_part_with(dir, symbol, day, 1, tick_e9, step_e9, FrameSink::new)
        .map_err(|e| anyhow::anyhow!("{symbol}: {e}"))
}

